dtsPropsFor.Dialog:
/** Heading text. Also the dialog's accessible name, via `aria-labelledby`. */
  title: string;
  /** Escape, a click on the scrim, and the close button all call this. */
  onClose: () => void;
  /** The body. `Dialog` renders the scrim, panel, title row and close button — everything below the title is the caller's. */
  children: React.ReactNode;

dtsPropsFor.FolderTree:
/** Library whose category tree is shown. */
  library: string;
  /** The selected folder, or `null` for the whole library. */
  selected: string | null;
  /** Fired when a row is chosen. `null` means the selection was cleared. */
  onSelect: (folder: string | null) => void;

dtsPropsFor.MovePartDialog:
/** The part being moved. */
  part: { id: string; name: string };
  /** The library the move happens within. Moves never cross libraries. */
  library: string;
  /** Called on cancel and after a completed move. */
  onClose: () => void;

dtsPropsFor.Detail:
/** One part's full record, exactly as `GET /api/parts/{id}` returns it (the ts-rs `PartDetail` type). */
  part: {
    id: string; library: string; revision: string; revLabel: string;
    name: string; partNumber: string | null; sourcePath: string;
    /** `data:image/webp;base64,...`, or null. */
    thumbnail: string | null;
    triangleCount: number | null; isWatertight: boolean | null;
    /** Millimetres. `approximate: true` means mesh-derived, and must be labelled so. */
    bboxMm: { value: [number, number, number]; approximate: boolean } | null;
    /** Absent for an open mesh, deliberately — integrating volume over one would lie. */
    volumeMm3: { value: number; approximate: boolean } | null;
    surfaceAreaMm2: { value: number; approximate: boolean } | null;
    kernelVersion: string | null; sourceHash: string | null;
    sourceFormat: string | null; sourceBytes: number | null;
    storedBytes: number | null; compressed: boolean | null;
    tessellationL0: string | null; tessellationL0Bytes: number | null;
    createdAt: string; updatedAt: string;
  };
  /** Controls for the header. The part page passes Remove; the quick-look passes none. */
  actions?: React.ReactNode;
  /** Whether the record-a-source form is offered. Off for the quick-look, on for the full page. */
  recordable?: boolean;
